import React, { useState, useRef, useEffect } from 'react';
import { analyzeMedicalArticle } from '../services/geminiService';
import Card from './ui/Card';
import LoadingSpinner from './ui/LoadingSpinner';
import { marked } from 'marked';
import mammoth from 'mammoth';
import * as pdfjsLib from 'pdfjs-dist';

// Configurar el worker de PDF.js usando CDN.
// Es crucial que la versión del worker coincida con la versión de la librería.
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;

const ArticleAnalyzer: React.FC = () => {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [analysis, setAnalysis] = useState<string | null>(null);
    const [file, setFile] = useState<File | null>(null);
    const [textInput, setTextInput] = useState('');
    const [inputType, setInputType] = useState<'upload' | 'text'>('upload');
    const [isKeySelected, setIsKeySelected] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        const checkApiKey = async () => {
            try {
                if ((window as any).aistudio && (window as any).aistudio.hasSelectedApiKey) {
                    const hasKey = await (window as any).aistudio.hasSelectedApiKey();
                    setIsKeySelected(hasKey);
                } else {
                     setIsKeySelected(true);
                }
            } catch (e) {
                setIsKeySelected(true);
            }
        };
        checkApiKey();
    }, []);

    const handleSelectKey = async () => {
        try {
            await (window as any).aistudio.openSelectKey();
            setIsKeySelected(true);
        } catch (e) {
            console.error(e);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setFile(e.target.files[0]);
            setError(null);
            setAnalysis(null);
        }
    };

    const convertFileToBase64 = (file: File): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = () => {
                const result = reader.result as string;
                const base64 = result.split(',')[1];
                resolve(base64);
            };
            reader.onerror = error => reject(error);
        });
    };

    const extractTextFromDocx = async (file: File): Promise<string> => {
        const arrayBuffer = await file.arrayBuffer();
        const result = await mammoth.extractRawText({ arrayBuffer });
        return result.value;
    };

    const extractTextFromPdf = async (file: File): Promise<string> => {
        try {
            const arrayBuffer = await file.arrayBuffer();
            // Cargar el documento PDF
            const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
            const pdf = await loadingTask.promise;

            let fullText = '';
            const numPages = pdf.numPages;

            // Iterar sobre todas las páginas
            for (let i = 1; i <= numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();

                // Filtrar items vacíos y unir
                const pageText = textContent.items
                    .filter((item: any) => 'str' in item && item.str.trim().length > 0)
                    .map((item: any) => item.str)
                    .join(' ');

                if (pageText.trim()) {
                    fullText += `\n\n--- Página ${i} ---\n${pageText}`;
                }
            }

            return fullText;
        } catch (error: any) {
            console.error("PDF Extraction Error:", error);
            if (error.name === 'PasswordException') {
                throw new Error("El PDF está protegido con contraseña. Por favor, desbloquéalo primero.");
            }
            throw new Error("Error al leer el PDF. Puede estar dañado o ser un formato no soportado.");
        }
    };

    const handleAnalyze = async () => {
        setIsLoading(true);
        setError(null);
        setAnalysis(null);

        try {
            let contentToAnalyze = '';
            let mimeType = 'text/plain';

            if (inputType === 'text') {
                if (!textInput.trim()) throw new Error("Por favor, pega el texto del artículo.");
                contentToAnalyze = textInput;
            } else {
                if (!file) throw new Error("Por favor, selecciona un archivo.");

                if (file.type === 'application/pdf') {
                    // Extracción de texto PDF en cliente
                    contentToAnalyze = await extractTextFromPdf(file);
                    if (!contentToAnalyze.trim()) {
                        throw new Error("No se pudo extraer texto del PDF. Es posible que sea un documento escaneado (imagen). Por favor, intenta subirlo como imagen (JPG/PNG) o usa una herramienta de OCR.");
                    }
                    mimeType = 'text/plain';
                } else if (file.type.startsWith('image/')) {
                    contentToAnalyze = await convertFileToBase64(file);
                    mimeType = file.type;
                } else if (
                    file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || 
                    file.name.endsWith('.docx')
                ) {
                    contentToAnalyze = await extractTextFromDocx(file);
                    mimeType = 'text/plain';
                } else if (file.type === 'text/plain') {
                    contentToAnalyze = await file.text();
                    mimeType = 'text/plain';
                } else {
                    throw new Error("Formato de archivo no soportado. Usa PDF, Word (.docx), Imagen o Texto.");
                }
            }

            const result = await analyzeMedicalArticle(contentToAnalyze, mimeType);
            setAnalysis(result);

        } catch (e: any) {
            console.error(e);
            let msg = "Ocurrió un error al analizar el artículo.";
            if (e.message) msg = e.message;
            if (msg.includes("413")) msg = "El archivo es demasiado grande. Intenta con un archivo más pequeño.";
            setError(msg);
        } finally {
            setIsLoading(false);
        }
    };

    const handleReset = () => {
        setFile(null);
        setAnalysis(null);
        setError(null);
        setTextInput('');
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    if (!isKeySelected) {
         return (
            <Card className="max-w-2xl mx-auto text-center">
                <h2 className="text-2xl font-bold text-blue-800 dark:text-cyan-300 mb-4">📄 Analizador de Artículos</h2>
                <p className="mb-6 text-gray-600 dark:text-gray-400">Esta función requiere acceso a la API de Gemini.</p>
                <button onClick={handleSelectKey} className="bg-blue-600 text-white font-bold py-3 px-6 rounded-lg hover:bg-blue-700 transition-colors">Seleccionar Clave de API</button>
            </Card>
        );
    }

    return (
        <Card className="max-w-5xl mx-auto">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-2xl font-bold text-blue-800 dark:text-cyan-300">📄 Analizador de Artículos Médicos (Tutor MBE)</h2>
                    <p className="text-sm text-gray-500 dark:text-gray-400">Sube un paper y aprende a analizarlo con la Taxonomía de Bloom.</p>
                </div>
                {(analysis || error) && (
                    <button onClick={handleReset} className="text-sm bg-gray-200 hover:bg-gray-300 text-gray-700 dark:bg-slate-600 dark:hover:bg-slate-500 font-semibold py-1 px-3 rounded-lg">
                        Nuevo Análisis
                    </button>
                )}
            </div>

            {!analysis && (
                <div className="space-y-6 animate-fade-in">
                    <div className="flex space-x-4 mb-4">
                        <button 
                            onClick={() => setInputType('upload')}
                            className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-colors ${inputType === 'upload' ? 'bg-blue-100 text-blue-700 border border-blue-300 dark:bg-slate-700 dark:text-blue-300' : 'bg-gray-50 text-gray-600 hover:bg-gray-100 dark:bg-slate-800 dark:text-gray-400'}`}
                        >
                            📂 Subir Archivo
                        </button>
                        <button 
                            onClick={() => setInputType('text')}
                            className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-colors ${inputType === 'text' ? 'bg-blue-100 text-blue-700 border border-blue-300 dark:bg-slate-700 dark:text-blue-300' : 'bg-gray-50 text-gray-600 hover:bg-gray-100 dark:bg-slate-800 dark:text-gray-400'}`}
                        >
                            ✏️ Pegar Texto
                        </button>
                    </div>

                    {inputType === 'upload' ? (
                        <div 
                            className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-xl p-8 text-center cursor-pointer hover:border-blue-500 dark:hover:border-purple-500 transition-colors bg-gray-50 dark:bg-slate-800/50"
                            onClick={() => fileInputRef.current?.click()}
                        >
                            <input 
                                type="file" 
                                ref={fileInputRef} 
                                onChange={handleFileChange} 
                                className="hidden" 
                                accept=".pdf,.docx,.doc,.txt,image/*" 
                            />
                            <div className="text-5xl mb-4">📄</div>
                            {file ? (
                                <div>
                                    <p className="font-semibold text-green-600 dark:text-green-400 text-lg">{file.name}</p>
                                    <p className="text-sm text-gray-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                                    <p className="text-xs text-gray-400 mt-2">Haz clic para cambiar de archivo</p>
                                </div>
                            ) : (
                                <div>
                                    <p className="text-lg font-medium text-gray-700 dark:text-gray-300">Arrastra un archivo aquí o haz clic para subir</p>
                                    <p className="text-sm text-gray-500 mt-2">Soporta: PDF, Word (.docx), Imágenes (JPG/PNG) o Texto</p>
                                </div>
                            )}
                        </div>
                    ) : (
                        <textarea
                            value={textInput}
                            onChange={(e) => setTextInput(e.target.value)}
                            placeholder="Pega aquí el contenido completo del artículo (Título, Abstract, Intro, Resultados, Discusión...)"
                            className="w-full h-64 p-4 rounded-xl border border-gray-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-gray-900 dark:text-gray-100 focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
                        />
                    )}

                    {error && <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">{error}</div>}

                    <button 
                        onClick={handleAnalyze} 
                        disabled={isLoading || (inputType === 'upload' && !file) || (inputType === 'text' && !textInput.trim())}
                        className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-bold py-4 px-6 rounded-xl hover:from-blue-700 hover:to-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-md transform hover:scale-[1.01]"
                    >
                        {isLoading ? 'Analizando artículo con IA...' : '🔍 Analizar Artículo'}
                    </button>
                    {isLoading && <LoadingSpinner />}
                </div>
            )}

            {analysis && (
                <div className="animate-fade-in mt-4">
                    <div className="bg-white dark:bg-slate-800 rounded-xl border dark:border-slate-700 overflow-hidden shadow-sm">
                        <div className="p-6 md:p-10 prose max-w-none dark:prose-invert prose-blue prose-headings:font-bold prose-h1:text-center prose-img:rounded-xl"
                            dangerouslySetInnerHTML={{ __html: marked.parse(analysis) }} 
                        />
                    </div>
                    <div className="mt-8 text-center">
                         <button onClick={handleReset} className="bg-blue-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-blue-700 dark:bg-purple-600 dark:hover:bg-purple-700 shadow-md">
                            Analizar otro artículo
                        </button>
                    </div>
                </div>
            )}
        </Card>
    );
};

