                                className={`flex-1 py-2 px-4 rounded-lg font-semibold transition-colors ${inputType === 'text' ? 'bg-blue-100 text-blue-700 border border-blue-300 dark:bg-slate-700 dark:text-blue-300' : 'bg-gray-50 text-gray-600 hover:bg-gray-100 dark:bg-slate-800 dark:text-gray-400'}`}
                            >
                                ✏️ Pegar Texto
                            </button>
                        </div>

                        {inputType === 'upload' ? (
                            <div 
                                className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-xl p-8 text-center cursor-pointer hover:border-blue-500 dark:hover:border-purple-500 transition-colors bg-gray-50 dark:bg-slate-800/50"
                                onClick={() => fileInputRef.current?.click()}
                            >
                                <input 
                                    type="file" 
                                    ref={fileInputRef} 
                                    onChange={handleFileChange} 
                                    className="hidden" 
                                    accept=".pdf,.docx,.doc,.txt,image/*" 
                                />
                                <div className="text-5xl mb-4">📄</div>
