// Configurar el worker de PDF.js.
// Usamos unpkg como fallback confiable.
const pdfJsVersion = pdfjsLib.version || '4.4.168';
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfJsVersion}/build/pdf.worker.min.mjs`;

// Configurar renderer personalizado para tablas desplazables y responsivas
const renderer = new marked.Renderer();
// @ts-ignore - Ignore type checking for the renderer method signature to ensure compatibility
renderer.table = (header: string, body: string) => {
    return `
    <div class="w-full my-6 overflow-hidden rounded-xl border border-gray-200 dark:border-slate-700 shadow-md">
        <div class="overflow-x-auto w-full">
            <table class="min-w-max w-full divide-y divide-gray-200 dark:divide-slate-700 text-sm md:text-base">
                <thead class="bg-gray-100 dark:bg-slate-900 text-gray-900 dark:text-white uppercase tracking-wider font-bold">
                    ${header}
                </thead>
                <tbody class="divide-y divide-gray-200 dark:divide-slate-700 bg-white dark:bg-slate-800 [&_td]:p-4 [&_td]:h-16 [&_td]:align-middle">
